def topological_sort(graph):
    visited = set()
    order = []
    for node in graph:
        if node not in visited:
            stack = [(node, False)]
            while stack:
                v, processed = stack.pop()
                if processed:
                    order.append(v)
                    continue
                if v in visited:
                    continue
                visited.add(v)
                stack.append((v, True))
                for neighbor in reversed(graph.get(v, [])):
                    if neighbor not in visited:
                        stack.append((neighbor, False))
    if len(order) != len(graph):
        return []
    return order

def topological_sort_with_validation(graph):
    indegree = {node: 0 for node in graph}
    for u in graph:
        for v in graph.get(u, []):
            indegree[v] = indegree.get(v, 0) + 1
    queue = [node for node in indegree if indegree[node] == 0]
    count = 0
    while queue:
        u = queue.pop()
        count += 1
        for v in graph.get(u, []):
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)
    if count != len(graph):
        return []
    return [u for u in graph if indegree[u] == 0] + [u for u in graph if indegree[u] > 0]

