def is_path_possible(grid):
    if not grid or not grid[0]:
        return False
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return False
        if grid[r][c] == 0 or (r, c) in visited:
            return False
        if r == rows - 1 and c == cols - 1:
            return True
        visited.add((r, c))
        for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            if dfs(r + dr, c + dc):
                return True
        return False
    return dfs(0, 0)

def find_path(grid):
    if not grid or not grid[0]:
        return []
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    path = []
    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return False
        if grid[r][c] == 0 or (r, c) in visited:
            return False
        visited.add((r, c))
        path.append((r, c))
        if r == rows - 1 and c == cols - 1:
            return True
        for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            if dfs(r + dr, c + dc):
                return True
        path.pop()
        return False
    dfs(0, 0)
    return path

