def find_valid_order(courses, prerequisites):
    graph = {c: [] for c in courses}
    indegree = {c: 0 for c in courses}
    for pre, course in prerequisites:
        graph[pre].append(course)
        indegree[course] = indegree.get(course, 0) + 1
    stack = [c for c in courses if indegree[c] == 0]
    order = []
    while stack:
        v = stack.pop()
        order.append(v)
        for neighbor in graph.get(v, []):
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                stack.append(neighbor)
    if len(order) != len(courses):
        return []
    return order

def find_valid_order_dfs(courses, prerequisites):
    graph = {c: [] for c in courses}
    for pre, course in prerequisites:
        graph[pre].append(course)
    visited = set()
    order = []
    def dfs(v):
        visited.add(v)
        for neighbor in graph.get(v, []):
            if neighbor not in visited:
                dfs(neighbor)
        order.append(v)
    for node in courses:
        if node not in visited:
            dfs(node)
    if len(order) != len(courses):
        return []
    return order[::-1]

